import {
  Box,
  Button,
  Card,
  CardContent,
  Container,
  Grid,
  Tooltip,
  Typography,
} from "@mui/material";
import React from "react";
import degreeImg from "../../../assets/images/teacher.svg";
import experienceImg from "../../../assets/images/briefcase.svg";
import locationImg from "../../../assets/images/location2.svg";
import { Link, useNavigate, useParams } from "react-router-dom";
import { ApiEndpoints } from "src/network/endpoints";
import { axiosInstance } from "src/network/adapter";
import { toastError, toastSuccess } from "src/utils/utils";
import { useEffect, useState } from "react";
import FallbackSpinner from "src/@core/components/spinner";

const CurrentOpenings = ({ title }) => {
  const [careerData, setCareerData] = useState([]);
  const [loading, setLoading] = useState(false);
  const { id } = useParams();
  const navigate = useNavigate();
  const handleOpeningsClick = (id) => {
    navigate(`/career-details/${id}`);
    window.scrollTo(0, 0);
  };
  const handleApplyNowClick = () => {
    navigate(`/career-details/${id}`);
    window.scrollTo(0, 0);
  };

  const fetchCareerData = () => {
    setLoading(true);
    axiosInstance
      .get(ApiEndpoints.CAREER.list)
      .then((response) => {
        const responseData = response.data.data;
        const activeData = responseData.filter(
          (item) => item.status === "active"
        );
        setCareerData(activeData);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  useEffect(() => {
    fetchCareerData();
  }, []);

  if (loading) return <FallbackSpinner />;
  return (
    <>
      <Box>
        <Container
          maxWidth={"xl"}
          sx={{ px: { xs: 5, lg: 15, xl: 20 }, pt: { xs: 3, md: 0, xl: 15 } }}
        >
          <Grid container rowGap={{ xs: 10, md: 10 }}>
            <Grid item xs={12}>
              <Typography
                sx={{
                  fontSize: { xs: "32px", sm: "36px", md: "46px", lg: "56px" },
                  lineHeight: {
                    xs: "38px",
                    sm: "53px",
                    md: "73px",
                    lg: "83px",
                  },
                  fontWeight: 500,
                  color: "#201D28",
                  textAlign: "center",
                }}
              >
                {title}
              </Typography>
            </Grid>
            <Grid
              item
              xs={12}
              sx={{ display: "flex", flexDirection: "column", gap: 5 }}
            >
              {careerData.map((item, index) => (
                <Card
                  sx={{
                    width: "100%",
                    boxShadow: "none",
                    border: "1px solid #B2B0C0",
                    borderRadius: "12px",
                    cursor: "pointer",
                  }}
                  key={index}
                  onClick={() => handleOpeningsClick(item.id)}
                >
                  <CardContent>
                    <Grid container rowGap={{ xs: 3, md: 0 }}>
                      <Grid
                        item
                        xs={12}
                        md={4}
                        sx={{
                          display: "flex",
                          flexDirection: "column",
                          gap: 1,
                        }}
                      >
                        <Tooltip title={item.position} arrow placement="top">
                          <Typography
                            sx={{
                              fontSize: "24px",
                              lineHeight: "36px",
                              fontWeight: 400,
                              color: "#000000",
                              whiteSpace: "nowrap",
                              overflow: "hidden",
                              textOverflow: "ellipsis",
                              maxWidth: "200px",
                            }}
                          >
                            {item.position}
                          </Typography>
                        </Tooltip>
                        <Tooltip title={item.department} arrow placement="top">
                          <Typography
                            sx={{
                              fontSize: "16px",
                              lineHeight: "26px",
                              fontWeight: 400,
                              color: "#69668E",
                              whiteSpace: "nowrap",
                              overflow: "hidden",
                              textOverflow: "ellipsis",
                              maxWidth: "200px",
                            }}
                          >
                            {item.department}
                          </Typography>
                        </Tooltip>
                      </Grid>
                      <Grid
                        item
                        xs={12}
                        md={2}
                        sx={{
                          display: "flex",
                          alignItems: "center",
                          gap: 2,
                        }}
                      >
                        <img src={degreeImg} />
                        <Tooltip title={item.education} arrow placement="top">
                          <Typography
                            sx={{
                              fontSize: "16px",
                              lineHeight: "24px",
                              fontWeight: 400,
                              color: "#000000",
                              whiteSpace: "nowrap",
                              overflow: "hidden",
                              textOverflow: "ellipsis",
                              maxWidth: "120px",
                            }}
                          >
                            {item.education}
                          </Typography>
                        </Tooltip>
                      </Grid>
                      <Grid
                        item
                        xs={12}
                        md={2}
                        sx={{
                          display: "flex",
                          alignItems: "center",
                          gap: 2,
                        }}
                      >
                        <img src={experienceImg} />
                        <Tooltip title={item.experience} arrow placement="top">
                          <Typography
                            sx={{
                              fontSize: "16px",
                              lineHeight: "24px",
                              fontWeight: 400,
                              color: "#000000",
                              whiteSpace: "nowrap",
                              overflow: "hidden",
                              textOverflow: "ellipsis",
                              maxWidth: "110px",
                            }}
                          >
                            {item.experience}
                          </Typography>
                        </Tooltip>
                      </Grid>
                      <Grid
                        item
                        md={2}
                        xs={12}
                        sx={{
                          display: "flex",
                          alignItems: "center",
                          gap: 2,
                        }}
                      >
                        <img src={locationImg} />
                        <Tooltip title={item.loaction} arrow placement="top">
                          <Typography
                            sx={{
                              fontSize: "16px",
                              lineHeight: "24px",
                              fontWeight: 400,
                              color: "#000000",
                              whiteSpace: "nowrap",
                              overflow: "hidden",
                              textOverflow: "ellipsis",
                              maxWidth: "150px",
                            }}
                          >
                            {item.loaction}
                          </Typography>
                        </Tooltip>
                      </Grid>
                      <Grid
                        item
                        md={2}
                        sx={{
                          display: "flex",
                          alignItems: "center",

                          justifyContent: "end",
                        }}
                      >
                        <Button
                          variant="contained"
                          sx={{ borderRadius: "16px", p: "3px 18px" }}
                          onClick={() => handleApplyNowClick(item.id)}
                        >
                          Apply Now
                        </Button>
                      </Grid>
                    </Grid>
                  </CardContent>
                </Card>
              ))}
            </Grid>
          </Grid>
        </Container>
      </Box>
    </>
  );
};

export default CurrentOpenings;
